git switch -q trust-root-format && python3 - <<'EOF'
import re
def sub(path, old, new):
    s = open(path).read()
    assert s.count(old) == 1, (path, old[:60])
    open(path, "w").write(s.replace(old, new))

d = "docs/provenance-design.md"
sub(d, """   Decided: a VSA subject's `gitCommit` is reported but not checked. A
   vendored skill usually has no `.git`, so the checker cannot recompute
   the revision, and the match is on the directory digest alone.""",
"""   Decided: a VSA subject must carry `gitCommit`, as the Source track
   requires, and its value must equal the operator record's `commit`; a
   missing or different value rejects the VSA. A vendored skill usually has
   no `.git`, so the checker cannot recompute the revision, but the record
   names it, so the comparison needs no repository.""")
sub(d, """       - issuer: https://token.actions.githubusercontent.com
         build_signer_uris:
           - "{source}/.github/workflows/release.yml@refs/heads/main"
     builders:
       - id: https://github.com/actions/runner/github-hosted
         build_type: https://actions.github.io/buildtypes/workflow/v1""",
"""       - issuer: https://token.actions.githubusercontent.com
         build_signer_uris:
           - "{source}/.github/workflows/release.yml@refs/heads/main"
         builders:
           - id: https://github.com/actions/runner/github-hosted
             build_type: https://actions.github.io/buildtypes/workflow/v1""")
sub(d, """     signer-to-source binding from question 2. When `build_signer_uris` is
     given, its Build Signer URI extension (`…1.9`) must equal one of them.
     The statement's `builder.id` and `buildType` must match one listed
     pair. The checker""",
"""     signer-to-source binding from question 2. Its Build Signer URI
     extension (`…1.9`) must equal one of that signer's required
     `build_signer_uris`, which binds the signer to one workflow path and
     ref rather than to any workflow in the repository. The statement's
     `builder.id` and `buildType` must match a pair listed under that same
     signer, since SLSA requires accepting only specific signer and builder
     pairs. The checker""")

s = "schema/trust-root.schema.json"
sub(s, """      "required": ["signers", "builders"],""", """      "required": ["signers"],""")
sub(s, """            "required": ["issuer"],
            "properties": {
              "issuer": { "$ref": "#/$defs/exact" },
              "build_signer_uris": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": { "$ref": "#/$defs/exact" }
              }
            }
          }
        },
        "builders": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["id", "build_type"],
            "properties": {
              "id": { "$ref": "#/$defs/exact" },
              "build_type": { "$ref": "#/$defs/exact" }
            }
          }
        }
      }""",
"""            "required": ["issuer", "build_signer_uris", "builders"],
            "properties": {
              "issuer": { "$ref": "#/$defs/exact" },
              "build_signer_uris": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": { "$ref": "#/$defs/exact" }
              },
              "builders": {
                "description": "The builder.id and buildType pairs this signer may claim.",
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": ["id", "build_type"],
                  "properties": {
                    "id": { "$ref": "#/$defs/exact" },
                    "build_type": { "$ref": "#/$defs/exact" }
                  }
                }
              }
            }
          }
        }
      }""")

t = "tests/test_provenance.py"
sub(t, """        ("build_provenance", {"builders": []}),""",
"""        ("build_provenance", {"builders": [{"id": "b", "build_type": "t"}]}),
        ("build_provenance", {"signers": [{"issuer": "i", "build_signer_uris": ["u"], "builders": []}]}),
        ("build_provenance", {"signers": [{"issuer": "i", "builders": [{"id": "b", "build_type": "t"}]}]}),""")
EOF
